   126      /* Bail out if we cannot construct at least a 1 char string. */
   127      const char *input = (const char *) data;
   128      if (size < 2 || input[size - 1] != '\0' || strchr(input, '\n')) {
   129          return 0;
   130      }
   131
   132      /* Disable logging to avoid write to disk. */
   133      static bool isInit = false;
   134      if (!isInit) {
   135          vlog_set_verbosity("off");
   136          isInit = true;
   137      }
   138
   139      /* Parse keys and wc keys. */
   140      parse_keys(false, input);
   141      parse_keys(true, input);
   142
   143      /* Parse actions. */
   144      parse_actions(input);
   145
   146      return 0;
